import org.mockito.internal.progress.ThreadSafeMockingProgress;
import static org.junit.Assert.*;
import static org.mockito.Matchers.isA;

public class Matchers_isA_TriageGen1Test {









    @Test
    public void testIsA_WithNullClass() {
        // Testing how the method handles a null class parameter if the implementation allows
        // Based on the signature, it expects Class<T>
        try {
            Object result = isA(null);
            // If the internal reportMatcher or InstanceOf throws NPE, the test passes via exception
            // If it returns null, we assert it.
            assertNull(result);
        } catch (NullPointerException e) {
            // This is an acceptable outcome for passing a null class to a matcher
        }
    }
}
